import { useCallback, useMemo } from 'react';

import {
  BasicContainer,
  BrandAvatarList,
  ComparisonLine,
  DataStateHandler,
  Skeleton,
  SubFilter,
  Waterfall,
} from 'components';
import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  useSubFilters,
} from 'hooks';
import type { FilterValue, Option } from 'models/Filters';
import { COMMERCIAL_RESULTS_WATERFALL_COLORS } from 'pages/pillars/ValueCreation/CommercialResults/config';
import { WaterfallConfig } from 'pages/pillars/ValueCreation/PerformanceTool/config/types';
import { WaterfallData } from 'pages/pillars/ValueCreation/PerformanceTool/types';
import { StyledTooltip } from 'shared/Styles';

import {
  COMMERCIAL_RESULTS_PAGE_NAME,
  COMMERCIAL_RESULTS_WATERFALL_OPTIONS_API_KEY_PREFIX,
  COMMERCIAL_RESULTS_WATERFALL_OPTIONS_DATA_API_KEY,
} from '../../../../constants';
import { useCommercialResultsWaterfallFilterSync } from '../../../../hooks/useCommercialResultsWaterfallFilterSync/useCommercialResultsWaterfallFilterSync';
import {
  getAvailableWaterfallOptions,
  resolveWaterfallFilterOnContextChange,
  shouldLockWaterfallToSku,
} from '../../../../utils/resolveCommercialResultsWaterfallOptions';
import {
  StyledChartContainer,
  StyledWaterfallContainer,
} from './WaterfallSection.styles';

interface WaterfallSectionProps {
  config: WaterfallConfig;
  title: string;
  measure?: string;
  tooltip?: string;
  data?: WaterfallData | null;
  loading: boolean;
  error?: Error | null;
  waterfallOptionsDataApiKey?: string;
  waterfallOptionsApiKeyPrefix?: string;
  skeletonProps?: React.ComponentProps<typeof Skeleton>;
}

type CommercialWaterfallOptionsValues = Record<
  string,
  { values?: Option[] } | Option[]
>;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const getWaterfallContextOptions = (
  filterData: unknown,
  contextKey: string,
): Option[] => {
  if (!isRecord(filterData)) {
    return [];
  }

  const values = filterData.values;
  if (!isRecord(values)) {
    return [];
  }

  const contextData = values[contextKey] as
    CommercialWaterfallOptionsValues[string] | undefined;

  if (!contextData) {
    return [];
  }

  if (Array.isArray(contextData)) {
    return contextData;
  }

  return contextData.values ?? [];
};

export const WaterfallSection: React.FC<WaterfallSectionProps> = ({
  config,
  title,
  measure,
  tooltip,
  loading,
  error,
  data: chartData,
  waterfallOptionsDataApiKey = COMMERCIAL_RESULTS_WATERFALL_OPTIONS_DATA_API_KEY,
  waterfallOptionsApiKeyPrefix = COMMERCIAL_RESULTS_WATERFALL_OPTIONS_API_KEY_PREFIX,
  skeletonProps = {
    height: '328px',
    width: '100%',
    length: 1,
    borderRadius: 'none',
  },
}) => {
  const { applied } = usePageFilterApplied(COMMERCIAL_RESULTS_PAGE_NAME);
  const { dataFilters } = usePageFilterData(COMMERCIAL_RESULTS_PAGE_NAME);
  const { applyDirect } = usePageFilterManagement(COMMERCIAL_RESULTS_PAGE_NAME);
  const { activeSubFilters, subFiltersData } = useSubFilters();

  const contextKey = useMemo(
    () => config.getContextKey(applied),
    [config, applied],
  );

  const rawOptions = useMemo<Option[]>(
    () =>
      getWaterfallContextOptions(
        subFiltersData[waterfallOptionsDataApiKey],
        contextKey,
      ),
    [subFiltersData, waterfallOptionsDataApiKey, contextKey],
  );

  const { handleWaterfallFilterChange, syncWaterfallFilterAfterDrill } =
    useCommercialResultsWaterfallFilterSync({
      contextKey,
      rawOptions,
    });

  const isWaterfallFilterDisabled = useMemo(
    () => config.isViewByDisabled(contextKey, activeSubFilters, applied),
    [config, contextKey, activeSubFilters, applied],
  );

  const transformOptions = useCallback(
    (options: Option[]) => {
      const availableOptions = getAvailableWaterfallOptions(
        applied,
        dataFilters,
        options,
      );

      const lockToSku = shouldLockWaterfallToSku(applied);

      if (
        (activeSubFilters?.waterfall_filter === 'sku' || lockToSku) &&
        !availableOptions.some((opt) => opt.value === 'sku')
      ) {
        const skuOption = options.find((opt) => opt.value === 'sku') ?? {
          value: 'sku',
          label: 'SKU',
        };
        return [...availableOptions, skuOption];
      }

      return availableOptions;
    },
    [applied, dataFilters, activeSubFilters?.waterfall_filter],
  );

  const resolveValueOnContextChange = useCallback(
    ({
      currentValue,
      availableOptions,
      defaultOption,
    }: {
      currentValue: FilterValue;
      availableOptions: Option[];
      defaultOption: FilterValue;
      contextKey: string;
    }) => {
      if (currentValue === 'sku' || shouldLockWaterfallToSku(applied)) {
        return 'sku';
      }

      return (
        resolveWaterfallFilterOnContextChange({
          currentValue,
          availableOptions,
        }) ?? String(defaultOption ?? '')
      );
    },
    [applied],
  );

  const normalizeKpiConfig = (value: string) => value.replaceAll('_', '-');

  const rightContent = useMemo(
    () => (
      <SubFilter.Select
        apiKey={`${waterfallOptionsApiKeyPrefix}_${normalizeKpiConfig(config.kpiName)}`}
        dataApiKey={waterfallOptionsDataApiKey}
        params={{}}
        stateKey="waterfall_filter"
        contextKey={contextKey}
        valueLabel="View by:"
        shape="pill"
        size="medium"
        chips
        clearChips={false}
        disabled={isWaterfallFilterDisabled}
        onValueChange={handleWaterfallFilterChange}
        transformOptions={transformOptions}
        resolveValueOnContextChange={resolveValueOnContextChange}
      />
    ),
    [
      config.kpiName,
      contextKey,
      isWaterfallFilterDisabled,
      handleWaterfallFilterChange,
      waterfallOptionsApiKeyPrefix,
      waterfallOptionsDataApiKey,
      transformOptions,
      resolveValueOnContextChange,
    ],
  );

  const disabledIndexes = useMemo(
    () => chartData?.disabledIndexes || [],
    [chartData?.disabledIndexes],
  );

  const handleBarClick = useCallback(
    (index: number | null) => {
      if (index === null && activeSubFilters?.waterfall_filter !== 'sku') {
        return;
      }
      config.handleBarClick({
        index: index,
        labels: chartData?.labels,
        activeSubFilters,
        dataFilters,
        applied,
        applyDirect,
        syncWaterfallFilterAfterDrill,
      });
    },
    [
      config,
      chartData?.labels,
      activeSubFilters,
      dataFilters,
      applied,
      applyDirect,
      syncWaterfallFilterAfterDrill,
    ],
  );

  const renderLegend = useCallback(() => {
    const brandsData = chartData?.images?.data?.map((brand, index) => {
      const { mainBrand, ...rest } = brand;
      const labelEntry = chartData?.labels?.[index];
      const country = Array.isArray(labelEntry) ? labelEntry[1] : undefined;

      return {
        ...rest,
        index,
        description: country || undefined,
        ...(mainBrand?.src ? { mainBrand } : {}),
      };
    });

    return (
      <>
        {brandsData?.length ? (
          <div style={{ marginTop: 8, marginBottom: 12 }}>
            <BrandAvatarList
              data={brandsData}
              length={chartData?.labels?.length ?? 0}
              borderConfig={{ marginLeft: 16, marginRight: 16 }}
              gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
            />
          </div>
        ) : null}
      </>
    );
  }, [chartData]);

  return (
    <BasicContainer
      header={{
        title,
        measure,
        titleSize: 'H4',
        tooltip: tooltip ? (
          <StyledTooltip size="small">{tooltip}</StyledTooltip>
        ) : undefined,
        rightContent,
      }}
      layout={{
        border: 'small',
        borderRadius: 'large',
        shadow: 'small',
        bodyPadding: false,
        bottomSeparator: 'border',
      }}
      fullWidth
    >
      <DataStateHandler
        loading={loading}
        error={error}
        empty={chartData?.empty || !chartData}
        skeletonProps={skeletonProps}
      >
        <StyledWaterfallContainer>
          <StyledChartContainer>
            <Waterfall
              values={chartData?.values || []}
              labels={chartData?.labels || []}
              formattedData={chartData?.formattedData}
              showLabels={false}
              options={{
                animation: false,
              }}
              colors={COMMERCIAL_RESULTS_WATERFALL_COLORS}
              interactiveConfig={{
                onBarSelect: handleBarClick,
                clickability: {
                  enabled: true,
                  disabledIndexes,
                },
                renderLegend,
                fillHeight: true,
                showTooltip: true,
              }}
            />
          </StyledChartContainer>
          {chartData?.comparisonLine?.data && (
            <div style={{ marginTop: 12 }}>
              <ComparisonLine
                data={chartData?.comparisonLine?.data}
                gridColumnsLength={chartData?.labels?.length}
                borderConfig={{ marginLeft: 16, marginRight: 16 }}
                gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
              />
            </div>
          )}
        </StyledWaterfallContainer>
      </DataStateHandler>
    </BasicContainer>
  );
};
